package com.android.spotted.model.sighting

import com.android.spotted.model.Location
import com.android.spotted.model.Pet.Species

/**
 * A pet seen by a passerby.
 *
 * Plain Kotlin types only (no Firebase `Timestamp` or `GeoPoint`), so ViewModels and their tests
 * never depend on Firebase.
 *
 * @property id Unique id, generated by [SightingRepository.getNewId].
 * @property reporterId UID of the user who reported the sighting.
 * @property location Where the pet was seen.
 * @property seenAtMillis When the pet was seen (epoch millis), not when the report was sent.
 * @property species Species of the pet that was seen.
 * @property photoUrl Download URL of the photo, if the passerby took one.
 * @property alertId Id of the lost-pet alert this sighting is linked to, if any.
 */
data class Sighting(
    val id: String,
    val reporterId: String,
    val location: Location,
    val seenAtMillis: Long,
    val species: Species,
    val photoUrl: String? = null,
    val alertId: String? = null,
)
